#!/usr/bin/env python3
"""Generate the reproducible exact 10 MiB DM10Cube C++ runtime."""
from __future__ import annotations
import argparse, base64, hashlib, zlib
from pathlib import Path

TARGET_BYTES = 10 * 1024 * 1024
BEGIN = b"/*SELF_RESERVOIR_BEGIN\n"
END = b"SELF_RESERVOIR_END*/\n"
ALPHABET = b"#%&()+,-.23456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_abcdefghijklmnopqrstuvwxyz{}~"
LINE_PAYLOAD = 113
SEED = b"DM10CUBE-GITHUB-CANONICAL-RESERVOIR-v1"
CORE_ZLIB_B64 = """"""


def deterministic_bytes(offset: int, count: int) -> bytes:
    out = bytearray(); counter = offset // 32
    while len(out) < count:
        digest = hashlib.sha256(SEED + counter.to_bytes(8, "little")).digest()
        out.extend(ALPHABET[value % len(ALPHABET)] for value in digest)
        counter += 1
    return bytes(out[:count])


def build() -> bytes:
    core = zlib.decompress(base64.b64decode(CORE_ZLIB_B64))
    remaining = TARGET_BYTES - len(core) - len(BEGIN) - len(END)
    if remaining <= 0: raise ValueError("embedded core is too large")
    reservoir = bytearray(); payload_offset = 0
    while remaining > 0:
        prefix = f"R{payload_offset:08X}:".encode("ascii")
        payload_len = min(LINE_PAYLOAD, max(0, remaining - len(prefix) - 1))
        record = prefix + deterministic_bytes(payload_offset, payload_len)
        if len(record) < remaining: record += b"\n"
        record = record[:remaining]
        if not record: raise RuntimeError("reservoir generator made no progress")
        reservoir.extend(record); remaining -= len(record); payload_offset += payload_len
    result = core + BEGIN + bytes(reservoir) + END
    if len(result) != TARGET_BYTES: raise AssertionError(len(result))
    return result


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=Path("dm10cube_10MiB.cpp"))
    parser.add_argument("--print-sha256", action="store_true")
    args = parser.parse_args()
    source = build(); args.output.parent.mkdir(parents=True, exist_ok=True); args.output.write_bytes(source)
    digest = hashlib.sha256(source).hexdigest()
    if args.print_sha256: print(digest)
    print(f"generated={args.output} bytes={len(source)} sha256={digest}")
    return 0

if __name__ == "__main__": raise SystemExit(main())
